 Here's an example C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

void fibonacci(int n, int a, int b, vector<int>& seq) {
    if (n <= 0) {
        cout << "Invalid input: number of sequence elements must be positive." << endl;
        return;
    }

    if (!isdigit(a > '0' && isdigit(a) && isdigit(b > '0' && isdigit(b))) {
        cout << "Invalid input: the first two integers must be numeric." << endl;
        return;
    }

    if (n == 1) {
        seq.push_back(a);
        return;
    }

    vector<int> temp;
    fibonacci(n - 1, b, a + b, temp);
    seq.insert(seq.end(), temp.begin(), temp.end());
    seq.push_back(a + b);
}

int main() {
    int num_elements, first, second;

    cout << "Enter the first two integers of the Fibonacci sequence: ";
    cin >> first >> second;

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    vector<int> sequence;
    fibonacci(num_elements, first, second, sequence);

    if (sequence.size() != num_elements) {
        cout << "Error: could not generate the required number of sequence elements." << endl;
        return 1;
    }

    cout << "Fibonacci sequence (" << num_elements << " elements):";
    for (const auto& elem : sequence) {
        cout << elem << ", ";
    }
    cout << sequence[sequence.size() - 1] << endl;

    return 0;
}
```

